/**
 * Dictionary Cache
 */
export class DictionaryCache {
  public dict: Uint8Array;
  private hashMap: Map<number, number[]>;
  private readonly MIN_MATCH = 4;
  private readonly MAX_MATCH = 18;

  /**
   * Create Cache Dictionary
   * @param dictionary {Uint8Array} Dictionary
   */
  constructor(dictionary: Uint8Array) {
    this.dict = dictionary;
    this.hashMap = new Map();
    for (let i = 0; i <= dictionary.length - this.MIN_MATCH; i++) {
      const hash = this.hash4(dictionary.subarray(i, i + this.MIN_MATCH));
      const positions = this.hashMap.get(hash) || [];
      positions.push(i);
      this.hashMap.set(hash, positions);
    }
  }

  private hash4(block: Uint8Array): number {
    return (block[0] << 24) | (block[1] << 16) | (block[2] << 8) | block[3];
  }

  /**
   * Find Match
   * @param data {Uint8Array} Data buffer
   * @param dataPos {number} Position
   * @returns {Object|null} Match or null
   */
  public findMatch(
    data: Uint8Array,
    dataPos: number
  ): { offset: number; length: number } | null {
    if (dataPos + this.MIN_MATCH > data.length) return null;
    const hash = this.hash4(data.subarray(dataPos, dataPos + this.MIN_MATCH));
    const positions = this.hashMap.get(hash);
    if (!positions) return null;
    let bestLen = 0;
    let bestOffset = 0;
    for (const dictPos of positions) {
      let len = this.MIN_MATCH;
      while (
        len < this.MAX_MATCH &&
        dataPos + len < data.length &&
        dictPos + len < this.dict.length &&
        data[dataPos + len] === this.dict[dictPos + len]
      ) {
        len++;
      }
      if (len > bestLen) {
        bestLen = len;
        bestOffset = dictPos;
        if (bestLen === this.MAX_MATCH) break;
      }
    }
    return bestLen >= this.MIN_MATCH
      ? { offset: bestOffset, length: bestLen }
      : null;
  }
}
